STYLE = old[0]["sim"].split("</style>", 1)[0] + "</style>"

def q(prompt, choices, answer, why):
    return [prompt, choices, answer, why]

def make(i, *, title, goal, tag, concept, example, use_case, practice, boundary,
         sim, js, questions, steps, expect, sources, visual, written,
         language="python"):
    x = deepcopy(old[i])
    x.update({"title": title, "goal": goal, "tag": tag, "concept": concept,
              "example": example, "use_case": use_case, "practice": practice,
              "boundary": boundary, "sim": STYLE + sim, "js": js,
              "questions": questions,
              "walkthrough": {"language": language, "steps": steps,
                              "expect": expect, "limit": boundary},
              "sources": sources, "visual_explanation": visual,
              "written_questions": written, "source_checked_on": DATE})
    for k in ("minutes", "product_sections", "product_comparison",
              "product_questions", "product_sources", "certification_alignment"):
        x.pop(k, None)
    return x

