L.append(make(1,
 title="A CompletableFuture timeout can end waiting while work keeps running",
 goal="Separate a caller's patience budget from cancellation of the underlying side effect.",
 tag="Java concurrency · timeout boundary",
 concept='''<p>A customer hangs up after two minutes. The kitchen may still be cooking the meal. A timeout tells the caller to stop waiting; it does not prove the worker stopped.</p><p><code>CompletableFuture.orTimeout</code> completes the future exceptionally when the deadline wins. <code>CompletableFuture</code> does not directly control the computation that completes it, so cancellation is exceptional completion, not guaranteed interruption of that work.</p>''',
 example='''<p>An order-pricing task needs 800 ms, but the API budget is 500 ms. The caller sees a timeout at 500 ms. Without a cooperative cancellation signal, the worker can still charge CPU or call a downstream service at 800 ms.</p>''',
 use_case={"when":"Use explicit timeout and cancellation design around remote calls, executor tasks, fan-out requests, and expensive computations.","example":"A pricing fan-out exceeds the HTTP deadline but its supplier call continues and consumes a scarce connection.","decision":"Set the caller deadline, then decide separately whether work is safe to continue, must receive a cooperative cancellation token, or needs idempotent side effects."},
 practice="Change the caller deadline and whether the worker cooperates. Watch caller state and worker state diverge.",
 boundary="The model uses milliseconds and booleans. It does not schedule threads, prove interruption, model ForkJoinPool, transport cancellation, memory visibility, executor rejection, race timing, or idempotency. The Java replay executes only the decision arithmetic.",
 sim='''<div id="world"><label>Caller timeout ms <input id="timeoutMs" type="range" min="200" max="1000" value="500" step="100"></label><label><input id="cooperative" type="checkbox"> worker checks cancellation</label><div id="futureWorld" class="world" aria-live="polite"></div></div>''',
 js="function paintFuture(){const deadline=+timeoutMs.value,finishes=800,timed=deadline<finishes,workerStops=timed&&cooperative.checked;futureWorld.innerHTML='<div class=step-flow><div class=\"node '+(timed?'fail':'ok')+'\"><strong>caller</strong><br>'+(timed?'timeout at '+deadline+' ms':'result at 800 ms')+'</div><div class=\"node '+(workerStops?'wait':timed?'fail':'ok')+'\"><strong>worker</strong><br>'+(workerStops?'stops cooperatively':timed?'still runs to 800 ms':'finishes normally')+'</div></div>';};timeoutMs.oninput=paintFuture;cooperative.onchange=paintFuture;paintFuture();",
 questions=[q("Caller times out at 500 ms; worker ignores cancellation. What follows?",["The caller stops waiting while work may continue","The JVM kills the thread","The side effect is rolled back"],0,"Timeout and work termination are different events."),q("Why add cooperative cancellation?",["To give underlying work a checked stop condition","To hide all exceptions","To increase the deadline"],0,"The task must participate in stopping."),q("What must still protect a remote write?",["Idempotency and server-side deadlines where supported","Only orTimeout","A larger thread pool"],0,"Client timeout alone does not undo an external effect.")],
 steps=[{"code":"int workMs = 800;","note":"The synthetic worker needs 800 ms."},{"code":"int timeoutMs = 500;","note":"The caller's patience budget is shorter."},{"code":"boolean callerTimedOut = timeoutMs < workMs;","note":"The caller deadline wins."},{"code":"boolean workerStillRunning = callerTimedOut; String outcome = callerTimedOut ? \"caller timed out; worker may continue\" : \"result returned\";","note":"Record the separate worker risk."}],
 expect={"workMs":"800","timeoutMs":"500","callerTimedOut":"true","workerStillRunning":"true","outcome":"caller timed out; worker may continue"},
 sources=[["Java 17 CompletableFuture","https://docs.oracle.com/en/java/javase/17/docs/api/java.base/java/util/concurrent/CompletableFuture.html","Official API; checked October 26, 2026"],["Java 17 Future","https://docs.oracle.com/en/java/javase/17/docs/api/java.base/java/util/concurrent/Future.html","Official API; checked October 26, 2026"]],
 visual="The split timeline answers whether the caller and worker share a lifecycle. The red worker card after a caller timeout makes continued resource use visible.",
 written=["Which async tasks in your services can outlive the request that created them?","What cancellation and idempotency contract protects the most expensive one?"], language="java"))

