 questions=[q("Tool starts at 90 ms; parallel guardrail trips at 120 ms. What is true?",["The tool may already have started","The side effect is impossible","Output guardrails ran first"],0,"Parallel mode trades a pre-start guarantee for latency."),q("When use blocking mode?",["When rejected input must not start model/tool work","Only for output formatting","To enable parallel tools"],0,"Blocking mode finishes validation first."),q("Why add tool guardrails too?",["Agent input guardrails run only at the first-agent boundary, not before every tool call","They replace authorization","They make every tool reversible"],0,"Validate at the boundary that owns the side effect.")],
