 sources=[["OpenAI Agents SDK guardrails","https://openai.github.io/openai-agents-python/guardrails/","Living official documentation; checked October 26, 2026"],["OpenAI Agents SDK guardrail reference","https://openai.github.io/openai-agents-python/ref/guardrail/","Living official API reference; checked October 26, 2026"]],
