 sim='''<div id="world"><label>Implant signal <input id="magSignal" type="range" min="1" max="10" value="7"></label><label>Tissue attenuation <input id="attenuation" type="range" min="0" max="8" value="3"></label><label>Sensor noise <input id="sensorNoise" type="range" min="1" max="5" value="2"></label><div id="magnetWorld" class="world" aria-live="polite"></div></div>''',
 js="function paintMagnet(){const received=Math.max(0,+magSignal.value-+attenuation.value),snr=received/+sensorNoise.value,ok=snr>=2;magnetWorld.innerHTML='<div class=step-flow><div class=\"node ok\">temporary magnetic patch<br>signal '+magSignal.value+'</div><div class=\"node wait\">tissue subtracts '+attenuation.value+'</div><div class=\"node '+(ok?'ok':'fail')+'\">skin array<br>SNR '+snr.toFixed(1)+' · '+(ok?'readable in toy model':'too noisy')+'</div></div>';};[magSignal,attenuation,sensorNoise].forEach(x=>x.oninput=paintMagnet);paintMagnet();",
 questions=[q("What makes the reported device unusual?",["A metal-free, bioresorbable magnet supports untethered sensing","It is a permanent steel pacemaker","It removes all tissue attenuation"],0,"The material combines magnetic function with planned disappearance."),q("What did the paper demonstrate?",["Preclinical multi-organ monitoring including four-week porcine cardiac tracking","A completed human trial","A universal MRI replacement"],0,"The evidence is impressive but preclinical."),q("What is the key deployment boundary?",["Human safety, degradation, calibration, manufacturing, and regulatory evidence remain","No sensor is needed","Bioresorption guarantees efficacy"],0,"Material behavior is only one part of a clinical system.")],
 steps=[{"code":"implant_signal = 7","note":"Set a synthetic magnetic signal."},{"code":"tissue_attenuation = 3","note":"Account for signal loss through tissue."},{"code":"sensor_noise = 2; received = max(0, implant_signal - tissue_attenuation)","note":"Compute the received signal."},{"code":"snr = received / sensor_noise; readable = snr >= 2","note":"Apply a declared teaching threshold."}],
 expect={"implant_signal":7,"tissue_attenuation":3,"sensor_noise":2,"received":4,"snr":2.0,"readable":True},
 sources=[["Wu et al., Bioresorbable metal-free molecular magnets enable untethered organ monitoring","https://www.nature.com/articles/s41563-026-02759-4","Nature Materials; published October 22, 2026; checked October 26, 2026"],["Nature Materials research articles","https://www.nature.com/nmat/research-articles","Journal collection; checked October 26, 2026"]],
