L.append(make(5,
 title="A protected environment holds the job before the runner sees its secrets",
 goal="Place the production approval boundary before runner assignment and environment-secret access.",
 tag="GitHub Actions · deployment environments",
 concept='''<p>A bank vault does not hand the key to a courier and then ask a manager for approval. Approval comes first; only then does the courier receive access.</p><p>When a job references a GitHub environment, its protection rules must pass before the job is sent to a runner. Environment secrets become available only after that boundary.</p>''',
 example='''<p>The build job produces digest <code>sha256:abc</code>. A deploy job references <code>production</code>. A required reviewer rejects it: no production runner starts and no environment secret is released. Approval sends the job to a runner, where the workflow explicitly maps the secret into the deployment step.</p>''',
 use_case={"when":"Use environments for production or regulated targets that need approvals, branch restrictions, wait timers, custom policy checks, scoped secrets, or deployment history.","example":"A Databricks bundle or Kubernetes image may deploy to staging automatically but needs production approval and a production-only credential.","decision":"Keep build artifacts immutable, put approval on the deployment job, scope secrets to the environment, and remember that approval does not validate the artifact by itself."},
 practice="Approve or reject the deployment. Watch the job, runner, and secret states change in order.",
 boundary="The model shows one job and one reviewer. It does not call GitHub, evaluate plan/repository availability, admin bypass, branch policies, wait timers, custom protection apps, concurrency, OIDC, reusable workflows, self-hosted runner risk, secret masking, or artifact integrity.",
 sim='''<div id="world"><label>Review <select id="envReview"><option value="pending">pending</option><option value="approved">approved</option><option value="rejected">rejected</option></select></label><div id="envWorld" class="world" aria-live="polite"></div></div>''',
 js="function paintEnv(){const s=envReview.value,go=s==='approved';envWorld.innerHTML='<div class=step-flow><div class=\"node '+(s==='pending'?'wait':go?'ok':'fail')+'\">protection: '+s+'</div><div class=\"node '+(go?'ok':'wait')+'\">runner '+(go?'assigned':'not assigned')+'</div><div class=\"node '+(go?'ok':'wait')+'\">environment secret '+(go?'available to job':'withheld')+'</div></div>';};envReview.onchange=paintEnv;paintEnv();",
 questions=[q("A production review is pending. Can the job read its environment secret?",["No; protection passes before runner assignment and secret access","Yes; pending is enough","Yes; all repository jobs share it"],0,"The environment boundary withholds the job and its secret."),q("What does approval not prove?",["That the artifact is trusted and correct","That a reviewer clicked approve","That the job references an environment"],0,"Artifact integrity needs separate controls."),q("Where should production approval live?",["On the job that references the protected environment","Only in a README","After the credential is used"],0,"The gate must precede access and deployment." )],
 steps=[{"code":"review = 'pending'","note":"The production protection rule is unresolved."},{"code":"runner_assigned = review == 'approved'","note":"A pending job has no runner."},{"code":"secret_available = runner_assigned","note":"The environment secret stays behind the same boundary."},{"code":"state = 'waiting for approval' if not runner_assigned else 'deploying'","note":"Expose the deployment state clearly."}],
 expect={"review":"pending","runner_assigned":False,"secret_available":False,"state":"waiting for approval"},
 sources=[["GitHub Docs: deployment environments","https://docs.github.com/en/actions/concepts/workflows-and-actions/deployment-environments","Living documentation; checked October 26, 2026"],["GitHub Docs: deployments and environments","https://docs.github.com/en/actions/reference/workflows-and-actions/deployments-and-environments","Living documentation; checked October 26, 2026"],["GitHub Docs: secrets","https://docs.github.com/en/actions/concepts/security/secrets","Living documentation; checked October 26, 2026"]],
 visual="The three-stage gate answers when the runner and secret exist. Pending and rejected reviews leave both downstream boxes visibly inactive.",
 written=["Which deployment jobs currently receive production credentials before a policy decision?","What separate artifact-integrity evidence should the reviewer inspect? "]))

L.append(make(6,
 title="OpenAPI readOnly and writeOnly describe direction; they do not authorize",
 goal="Use directional schema annotations without mistaking generated-client behavior for server-side access control.",
 tag="OpenAPI 3.1.2 · directional schemas",
 concept='''<p>A restaurant menu marks “staff writes this field” and “customer sees this field.” The ink on the menu does not lock the kitchen door.</p><p>In OpenAPI 3.1.2, <code>readOnly</code> and <code>writeOnly</code> are annotations. Tooling may use request/response direction during validation, documentation, and code generation. Your server must still enforce authorization and response filtering.</p>''',
 example='''<p><code>id</code> is <code>readOnly</code>; clients should not control it on create. <code>password</code> is <code>writeOnly</code>; the response should not expose it. A malicious caller can still send <code>id</code>, and a buggy serializer can still leak <code>password</code>, unless runtime code rejects or strips them.</p>''',
 use_case={"when":"Use these annotations when one resource schema has fields that differ between request and response directions.","example":"A user-create request accepts password but a user response returns server-generated id and never returns password.","decision":"Use annotations for contract/tooling clarity, then add runtime request validation, output serialization tests, field-level authorization, and secret-handling controls. Separate schemas may be clearer for materially different shapes."},
 practice="Choose request or response direction and toggle runtime enforcement. Watch annotations and actual payload behavior diverge.",
 boundary="The browser models three fields and one policy. It does not run an OpenAPI validator or generator, select a JSON Schema dialect, model PUT nuances, required fields, nested schemas, references, security requirements, serialization libraries, or implementation-specific annotation behavior.",
 sim='''<div id="world"><label>Direction <select id="apiDirection"><option value="request">request</option><option value="response">response</option></select></label><label><input id="runtimeEnforcement" type="checkbox"> runtime enforcement enabled</label><div id="schemaDirectionWorld" class="world" aria-live="polite"></div></div>''',
 js="function paintDirection(){const req=apiDirection.value==='request',enforce=runtimeEnforcement.checked;const shown=req?['name','password']:['id','name'];const leaked=!req&&!enforce;schemaDirectionWorld.innerHTML='<div class=row><div class=\"node ok\"><strong>annotation suggests</strong><br>'+shown.join(', ')+'</div><div class=\"node '+(enforce?'ok':'fail')+'\"><strong>runtime payload</strong><br>'+(leaked?'id, name, password ← leak':'matches enforced direction')+'</div></div>';};apiDirection.onchange=paintDirection;runtimeEnforcement.onchange=paintDirection;paintDirection();",
 questions=[q("password is writeOnly in the schema. What guarantees it is absent from responses?",["Server-side serialization and tests, not the annotation alone","The word writeOnly by itself","CORS"],0,"The specification treats it as an annotation."),q("Why mark id readOnly?",["To communicate that the server owns the response field direction","To authenticate users","To encrypt the value"],0,"It clarifies the interface to tools and humans."),q("When prefer separate request/response schemas?",["When directional shapes and requirements differ enough that one annotated schema becomes ambiguous","Whenever an API has one field","To replace authorization"],0,"Clarity can outweigh schema reuse.")],
 steps=[{"code":"schema = {'id': 'readOnly', 'name': 'both', 'password': 'writeOnly'}","note":"Describe intended field directions."},{"code":"request_fields = [k for k, v in schema.items() if v != 'readOnly']","note":"Derive the teaching request shape."},{"code":"response_fields = [k for k, v in schema.items() if v != 'writeOnly']","note":"Derive the teaching response shape."},{"code":"runtime_authorization_required = True","note":"Keep enforcement explicit and separate."}],
 expect={"schema":{"id":"readOnly","name":"both","password":"writeOnly"},"request_fields":["name","password"],"response_fields":["id","name"],"runtime_authorization_required":True},
 sources=[["OpenAPI Specification 3.1.2: validating readOnly and writeOnly","https://spec.openapis.org/oas/v3.1#validating-read-only-and-write-only","Official specification; checked October 26, 2026"],["JSON Schema 2020-12 validation: readOnly/writeOnly","https://json-schema.org/draft/2020-12/json-schema-validation#name-a-vocabulary-for-basic-meta-d","Official specification; checked October 26, 2026"]],
 visual="The side-by-side contract and runtime payload answer whether a directional annotation actually removed a field. Turning enforcement off creates a visible password leak.",
 written=["Which fields in your APIs are direction-specific but currently rely only on generated-client behavior?","Would one annotated schema or separate request/response schemas be clearer for your highest-risk resource? "]))

